function orderDetailPage(order){const items=(store.order_items||[]).filter(item=>item.order_id===order.id),invoice=found('invoices',order.invoice_id);return `<div class="toolbar">${opsButton('All orders','order-back')}<div class="page-actions">${editbtn('orders',order.id,'Edit customer details')}${newOperation('order_items','Add product',order.business_id,'',`data-order="${esc(order.id)}"`)}</div></div>${card(order.title,`<div class="card-body"><div class="ops-card-top"><div><h3>${esc(order.buyer)}</h3><p>${esc(order.phone)} · ${esc(order.channel)}</p></div>${opsBadge(order.status)}</div><p class="notice">${esc(order.address)}</p><div class="page-actions section-gap">${(ORDER_NEXT[order.status]||[]).map(status=>opsButton(status,'op-status',`data-entity="orders" data-id="${esc(order.id)}" data-status="${status}"`)).join('')}${safeLink(order.tracking_url,'Track shipment')}</div></div>`)}<section class="section-gap">${items.length?table(['Product / SKU','Quantity','Unit price','Line total',''],items.map(item=>`<tr><td>${esc(item.title)}<span class="muted">${esc(found('products',item.product_id)?.sku||'')}</span></td><td>${item.quantity}</td><td>${money(item.unit_price)}</td><td>${money(item.quantity*item.unit_price)}</td><td>${editbtn('order_items',item.id)}</td></tr>`).join('')):empty('Add the ordered products','Select the size/color SKU and agreed quantity.',newOperation('order_items','Add product',order.business_id,'',`data-order="${esc(order.id)}"`))}</section><div class="two-column section-gap">${card('Order pricing',`<div class="card-body"><dl class="key-value"><div><dt>Shipping / discount</dt><dd>${money(order.shipping)} / ${money(order.discount)}</dd></div><div><dt>Order total</dt><dd>${money(orderAmount(order))}</dd></div></dl><p class="notice">An order is not cash income until an invoice payment is recorded.</p></div>`)}${card('Payment record',`<div class="card-body">${invoice?`<p>${esc(invoice.title)}</p><p class="section-gap">Paid ${money(invoice.paid)} · Outstanding ${money(balance(invoice))}</p><div class="page-actions section-gap">${balance(invoice)>0?opsButton('Record payment','payment',`data-id="${esc(invoice.id)}"`,true):''}${editbtn('invoices',invoice.id)}</div>`:`<p class="muted">Confirm the order and check the item prices before invoicing.</p><div class="section-gap">${opsButton('Create order invoice','op-call',`data-path="orders/${esc(order.id)}/invoice"`,true)}</div>`}</div>`)}</div>`;}
