function leadDetails(lead){const activities=(store.lead_activities||[]).filter(item=>item.lead_id===lead.id).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="toolbar">${opsButton('All leads','lead-back')}<div class="page-actions">${editbtn('leads',lead.id,'Edit research')}${newOperation('lead_activities','Log activity','qfs','',`data-lead="${esc(lead.id)}"`)}</div></div><div class="two-column">${card(lead.name,`<div class="card-body"><div class="ops-card-top">${badge(lead.stage)}${lead.verified?badge('Verified'):badge('Needs verification')}${sampleTag(lead)}</div><dl class="key-value section-gap"><div><dt>Buyer / market / product fit</dt><dd>${esc(lead.contact||'Contact not collected')} · ${esc(lead.role)}<br>${esc(lead.country)} · ${esc(lead.product_interest)}</dd></div><div><dt>Contact information</dt><dd>${esc(lead.email||'Email not collected')}<br>${esc(lead.phone)}</dd></div><div><dt>Next action</dt><dd>${esc(lead.next_action||'Set a concrete next action')}<br>${shortDate(lead.next_date)}</dd></div><div><dt>Research notes</dt><dd>${esc(lead.notes||'Record evidence and what makes this buyer a fit.')}</dd></div></dl><div class="page-actions section-gap">${safeLink(lead.website,'Company website')}${safeLink(lead.source_url,'Source evidence')}${opsButton('Research task','lead-task',`data-id="${esc(lead.id)}"`)}${opsButton('Export brief','lead-export',`data-id="${esc(lead.id)}"`)}</div></div>`)}${card('Research & contact history',activities.length?`<div class="row-list">${activities.map(activity=>`<div class="list-row"><div class="grow"><strong>${esc(activity.title)}</strong><p>${shortDate(activity.date)} · ${esc(activity.type)}</p><p>${esc(activity.outcome)}</p>${activity.next_date?`<p>Next follow-up ${shortDate(activity.next_date)}</p>`:''}</div>${editbtn('lead_activities',activity.id)}</div>`).join('')}</div>`:empty('Build an evidence trail','Log research, contact attempts and conversation outcomes.'))}</div>`;}
function qfsPage(){
  const leads=byBusiness('leads','qfs').filter(lead=>!leadQuery||[lead.name,lead.country,lead.product_interest,lead.contact].join(' ').toLowerCase().includes(leadQuery.toLowerCase()));
  const open=leads.filter(lead=>!['Won','Lost'].includes(lead.stage)),followups=open.filter(lead=>lead.next_date&&lead.next_date<=today());
  let html=businessIntro('qfs','Collect and qualify apparel buyers. Keep source evidence and the next action with every contact.',newOperation('leads','Collect a lead','qfs'));
  html+=`<div class="ops-context"><div><span class="eyebrow">Find → research → verify → qualify → follow up</span><p>Product fit: denim · leisurewear · sweaters · workwear · corporate wear</p></div><div class="page-actions">${opsButton('Import CSV / JSON','lead-import')}${opsButton('Export leads','leads-export')}</div></div><div class="stats">${stat('Open buyers',open.length,'Research and opportunity pipeline','sales',true)}${stat('Verified contacts',leads.filter(lead=>lead.verified).length,'Manually checked evidence','check')}${stat('Follow-ups due',followups.length,'Today or overdue','clock')}${stat('Potential value',money(total(open,'value')),'Estimated deals · not cash revenue','finance')}</div>`;
  html+=tabs('qfsTab',qfsTab,[['pipeline','Buyer pipeline'],['research','Research table'],['followups','Follow-ups']]);
  const selected=leads.find(lead=>lead.id===selectedLead);if(selected)return html+leadDetails(selected);
  html+=`<form class="ops-search section-gap" data-ops-search="leads"><input name="q" value="${esc(leadQuery)}" placeholder="Company, market or product" aria-label="Search QFS leads"><button class="btn secondary compact">Search</button></form>`;
  const leadRow=lead=>`<tr><td>${opTitle(lead)}<span class="muted">${esc(lead.website)}</span></td><td>${esc(lead.country)}<span class="muted">${esc(lead.product_interest)}</span></td><td>${esc(lead.contact)}<span class="muted">${esc(lead.email)}</span></td><td>${lead.verified?badge('Verified'):badge('Needs verification')}<span class="muted">Fit ${lead.score}/100</span></td><td>${shortDate(lead.next_date)}</td><td>${opsButton('Research','lead-open',`data-id="${esc(lead.id)}"`)}</td></tr>`;
  if(qfsTab==='pipeline')html+=`<div class="board ops-lead-board section-gap">${['Lead','Qualified','Contacted','Meeting','Proposal','Negotiation','Won','Lost'].map(stage=>`<section class="board-column"><div class="board-title">${stage}<span>${leads.filter(lead=>lead.stage===stage).length}</span></div>${leads.filter(lead=>lead.stage===stage).map(lead=>`<article class="board-item">${sampleTag(lead)}<h3>${esc(lead.name)}</h3><p>${esc(lead.country||'Market not recorded')} · ${esc(lead.product_interest||'Product fit not recorded')}</p><p>${lead.verified?'Verified contact':'Needs verification'} · Fit ${lead.score}/100</p><p>${shortDate(lead.next_date)}</p><div class="actions">${opsButton('Research','lead-open',`data-id="${esc(lead.id)}"`)}</div></article>`).join('')||'<p class="muted small">No buyers in this stage.</p>'}</section>`).join('')}</div>`;
  else html+=table(['Buyer','Market / product','Contact','Verification','Follow-up',''],(qfsTab==='followups'?followups:leads).map(leadRow).join(''));
  return html+'<p class="notice">Imports accept a leads JSON array or CSV columns: name, website, contact, email, phone, country, role, product_interest, source, source_url, next_date, notes. Duplicates are skipped. No outreach is sent.</p>';
}

