function mediaPage(){const bid=['cnmotos','alabama','jubayer'].includes(scope)?scope:'cnmotos',articles=byBusiness('articles',bid);let html=businessIntro(bid,bid==='jubayer'?'Plan your own ideas, articles, videos and brand development.':'Source-backed editorial work, article drafts and social repurposing.',newOperation('articles','New story',bid));html+=`<div class="ops-context"><div><span class="eyebrow">Research → draft → verify → approve → repurpose</span><p>${esc(business(bid)?.pillars||'Editorial and personal content')}</p></div><select id="media-business" aria-label="Editorial business">${['cnmotos','alabama','jubayer'].map(id=>option(id,bname(id),bid)).join('')}</select></div><div class="stats">${stat('Story pipeline',articles.filter(a=>a.status!=='Published').length,'Research and production','reports',true)}${stat('Needs verification',articles.filter(a=>!a.source_verified).length,'Check sources and claims','alert')}${stat('Ready stories',articles.filter(a=>a.status==='Ready').length,'Approved for publishing work','check')}${stat('Social drafts',byBusiness('content',bid).filter(c=>c.article_id&&c.status!=='Published').length,'Repurposed copy needs review','content')}</div>`+tabs('mediaTab',mediaTab,[['articles','Editorial stories'],['tasks','Work queue'],['website','Website maintenance']]);if(mediaTab==='tasks')return html+taskRows(byBusiness('tasks',bid).filter(task=>task.status!=='Done'));if(mediaTab==='website')return html+websiteWorkPage(bid);return html+`<div class="two-column">${articles.map(a=>`<article class="card business-card"><div class="ops-card-top"><h3>${esc(a.title)}</h3>${opsBadge(a.status)}</div><p>${esc(a.category)} · ${shortDate(a.due)} · ${a.source_verified?'Source checked':'Source not checked'}</p><p>${esc(a.summary).slice(0,220)}</p><div class="page-actions">${editbtn('articles',a.id,'Open story')}${safeLink(a.source_url,'Primary source')}${safeLink(a.published_url,'Live article')}${['Ready','Published'].includes(a.status)?opsButton('Create 5 social drafts','op-call',`data-path="articles/${esc(a.id)}/repurpose"`):''}</div></article>`).join('')||empty('Build a verified story queue','Collect a source, write the summary and draft, then review before publishing.',newOperation('articles','New story',bid))}</div><p class="notice">Published is manually confirmed with the live URL. Social drafts use the saved summary and still need your review.</p>`;}
function travelPage(){const bid='ghuraghuri',trips=byBusiness('trips',bid),requests=byBusiness('bookings',bid);let html=businessIntro(bid,'Operate your Bangladesh trip marketplace: agencies, guides, listings and traveler requests.',newOperation('bookings','Log booking request',bid));html+=`<div class="stats">${stat('Listed trips',trips.filter(t=>t.status==='Listed').length,'Current marketplace supply','businesses',true)}${stat('Partners',byBusiness('travel_partners',bid).length,'Travel agencies and guides','clients')}${stat('Open requests',requests.filter(r=>!['Confirmed','Cancelled'].includes(r.status)).length,'Needs contact or partner response','tasks')}${stat('Confirmed travelers',requests.filter(r=>r.status==='Confirmed').reduce((n,r)=>n+r.quantity,0),'Manually recorded confirmations','check')}</div>`+tabs('travelTab',travelTab,[['trips','Trip listings'],['partners','Agencies & guides'],['requests','Booking requests'],['website','Website work']]);if(travelTab==='trips')html+=`<div class="toolbar"><p class="muted small">Keep dates, itinerary, partner and capacity with each listing.</p>${newOperation('trips','New trip listing',bid)}</div>`+opRows('trips',trips,[['Trip',opTitle],['Partner',t=>esc(found('travel_partners',t.partner_id)?.name||'')],['Dates',t=>shortDate(t.start_date)+' – '+shortDate(t.end_date)],['Price',t=>money(t.price)],['Status',t=>opsBadge(t.status)]]);if(travelTab==='partners')html+=`<div class="toolbar"><p class="muted small">Onboard and verify the agencies and guides supplying your listings.</p>${newOperation('travel_partners','Add partner',bid)}</div>`+opRows('travel_partners',byBusiness('travel_partners',bid),[['Partner',opTitle],['Type',p=>esc(p.type)],['Contact',p=>esc(p.phone)],['Status',p=>opsBadge(p.status)]]);if(travelTab==='requests')html+=opRows('bookings',requests,[['Request',opTitle],['Traveler',r=>esc(r.contact)+'<span class="muted">'+esc(r.phone)+'</span>'],['Trip',r=>esc(found('trips',r.trip_id)?.title||'')],['Travelers',r=>r.quantity],['Stage',r=>opsBadge(r.status)],['Follow-up',r=>shortDate(r.next_date)]]);if(travelTab==='website')html+=websiteWorkPage(bid);return html+'<p class="notice">These are your private operating records. Live website bookings and listings are not automatically synchronized.</p>';}

function reportExport(report){const content=store.content.filter(c=>c.business_id==='artbit'&&c.client_id===report.client_id&&(report.retainer_id?c.retainer_id===report.retainer_id:monthOf(c)===report.month));return `${cname(report.client_id)} — ${report.month}\nPrepared by Artbit Studio\n\nDELIVERY\nPublished: ${content.filter(c=>c.status==='Published').length}\nApproved / planned: ${content.filter(c=>['Approved','Scheduled'].includes(c.status)).length}\nAwaiting review: ${content.filter(c=>c.status==='In review').length}\n\nRECORDED PLATFORM RESULTS\nReach: ${report.reach}\nEngagements: ${report.engagement}\nInquiries: ${report.inquiries}\nAd spend: ${money(report.spend)}\n\nWINS\n${report.wins}\n\nBLOCKERS\n${report.blockers}\n\nNEXT MONTH\n${report.next_steps}\n\nFigures are manually recorded. ${content.some(c=>c.demo)?'Sample content is included.':''}`;}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw new Error('CSV has an unclosed quote.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);const headers=(rows.shift()||[]).map(h=>h.replace(/^\uFEFF/,'').trim().toLowerCase());if(!headers.includes('name'))throw new Error('CSV needs a name column.');const allowed=new Set(['name','website','contact','email','phone','country','role','product_interest','source','source_url','next_date','next_action','notes']);return rows.map(values=>Object.fromEntries(headers.filter(h=>allowed.has(h)).map(h=>[h,values[headers.indexOf(h)]?.trim()||''])));}
function importLeads(){const input=document.createElement('input');input.type='file';input.accept='.csv,.json,text/csv,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>4*1024*1024)return toast('Choose a file smaller than 4 MB.',true);try{const text=await file.text();const payload=file.name.toLowerCase().endsWith('.csv')?{leads:parseCSV(text)}:JSON.parse(text);if(Array.isArray(payload))throw new Error('Use a JSON object with a leads array.');const result=await api('import-leads','POST',payload);await refresh();selectedLead='';render();toast(`${result.record.count} leads imported; ${result.record.duplicates} duplicates skipped.`);}catch(error){toast(error.message,true);}};input.click();}
function csvCell(value){let text=String(value??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
  const handled=['op-new','op-tab','op-status','op-call','op-delete','task-detail','artbit-client','artbit-content','order-open','order-back','lead-open','lead-back','lead-task','lead-import','lead-export','leads-export','client-report-export'];
  if(!handled.includes(action))return;event.preventDefault();el.disabled=true;
  try{
    if(action==='op-new'){
      const entity=el.dataset.entity,bid=el.dataset.business,defaults={business_id:bid,client_id:el.dataset.client||'',owner:store.settings.owner||'Jubayer'};
      if(entity==='tasks')Object.assign(defaults,{status:'Open',priority:'Medium',recurrence:'None'});
      if(entity==='retainers')Object.assign(defaults,{month:artbitMonth,status:'Draft',package:'Custom'});
      if(entity==='client_reports')Object.assign(defaults,{month:artbitMonth,status:'Draft'});
      if(entity==='orders')Object.assign(defaults,{status:'New',date:today(),title:'Order '+today()});
      if(['batches','order_items','bookings'].includes(entity))defaults.quantity=1;
      if(entity==='order_items'){defaults.order_id=el.dataset.order;const product=byBusiness('products',bid).find(p=>p.status==='Active')||byBusiness('products',bid)[0];if(product)Object.assign(defaults,{product_id:product.id,title:product.name+' · '+product.sku,unit_price:product.price});}
      if(entity==='bookings')defaults.date=today();
      if(entity==='lead_activities')Object.assign(defaults,{lead_id:el.dataset.lead,date:today()});
      if(entity==='designs')defaults.partner='Biggan PiC';
      if(entity==='leads')Object.assign(defaults,{stage:'Lead',next_action:'Research company and verify a buyer contact'});
      openEditor(entity,'',defaults);
    }
    if(action==='op-tab'){
      const group=el.dataset.group,value=el.dataset.tab;
      if(group==='artbitTab')artbitTab=value;if(group==='merchTab')merchTab=value;if(group==='qfsTab')qfsTab=value;if(group==='videoTab')videoTab=value;if(group==='mediaTab')mediaTab=value;if(group==='travelTab')travelTab=value;if(group==='taskView')taskView=value;
      render();
    }
    if(action==='op-status'){await api(el.dataset.entity+'/'+el.dataset.id,'PATCH',{status:el.dataset.status});await refresh();render();toast('Work updated.');}
    if(action==='op-call'){const result=await api(el.dataset.path,'POST',{});await refresh();render();toast(typeof result.record.count==='number'?`${result.record.count} work items created. Repeating this action keeps existing items.`:'Invoice is ready in Finance.');}
    if(action==='op-delete'){await api(el.dataset.entity+'/'+el.dataset.id,'DELETE',{});await refresh();if(el.dataset.task)taskDetail(el.dataset.task);else render();}
    if(action==='task-detail')taskDetail(el.dataset.id);
    if(action==='artbit-client'){artbitClient=el.dataset.id;artbitTab='overview';render();}
    if(action==='artbit-content'){scope='artbit';contentClient=el.dataset.client||artbitClient;go('content');}
    if(action==='order-open'){selectedOrder=el.dataset.id;merchTab='orders';render();}
    if(action==='order-back'){selectedOrder='';render();}
    if(action==='lead-open'){selectedLead=el.dataset.id;render();}
    if(action==='lead-back'){selectedLead='';render();}
    if(action==='lead-task'){const lead=found('leads',el.dataset.id);openEditor('tasks','',{title:'Research '+lead.name,business_id:'qfs',lead_id:lead.id,status:'Open',priority:'High',category:'Lead research',due:lead.next_date,owner:store.settings.owner,notes:lead.next_action});}
    if(action==='lead-import')importLeads();
    if(action==='lead-export'){const lead=found('leads',el.dataset.id);download('qfs-lead-'+lead.id+'.txt',`${lead.name}\nMarket: ${lead.country}\nProduct: ${lead.product_interest}\nContact: ${lead.contact} / ${lead.role}\nEmail: ${lead.email}\nWebsite: ${lead.website}\nSource: ${lead.source_url}\nVerified: ${lead.verified?'Yes':'No'}\nFit score: ${lead.score}/100\n\nRESEARCH\n${lead.notes}\n\nNEXT ACTION\n${lead.next_action}\nDue: ${lead.next_date}\n\nNo outreach has been sent from GROW.`);}
    if(action==='leads-export'){const headers=['name','website','contact','email','phone','country','role','product_interest','source','source_url','next_date','next_action','notes'];download('qfs-leads-'+today()+'.csv','\uFEFF'+[headers,...byBusiness('leads','qfs').map(lead=>headers.map(key=>lead[key]))].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
    if(action==='client-report-export'){const report=found('client_reports',el.dataset.id);download('artbit-report-'+report.month+'-'+report.id+'.txt',reportExport(report));}
  }catch(error){if($('#editor').open)formError(error);else toast(error.message,true);}finally{if(el.isConnected)el.disabled=false;}
});
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.id==='content-client'){contentClient=el.value;render();}
  if(el.id==='field-business_id'||el.id==='field-client_id'){const form=el.closest('form');if(form?.dataset.entity){const config=configs[form.dataset.entity],record={business_id:$('#field-business_id')?.value||'',client_id:$('#field-client_id')?.value||''};for(const f of config.fields.filter(f=>f.type==='ref'&&f.key!=='client_id')){const target=$('#field-'+f.key);if(target)target.innerHTML=referenceOptions(f,record,form.dataset.entity).map(([id,label])=>option(id,label,'')).join('');}}}
  if(el.id==='artbit-client'){artbitClient=el.value;render();}if(el.id==='artbit-month'){artbitMonth=el.value||today().slice(0,7);render();}if(el.id==='task-filter'){taskFilter=el.value;render();}if(el.id==='media-business'){scope=el.value;render();}
  if(el.dataset.stepId){try{await api('task_steps/'+el.dataset.stepId,'PATCH',{completed:el.checked});await refresh();render();}catch(error){el.checked=!el.checked;toast(error.message,true);}}
  if(el.id==='field-package'&&ARTBIT_PACKAGES[el.value])for(const[key,value]of Object.entries(ARTBIT_PACKAGES[el.value])){const fieldEl=$('#field-'+key);if(fieldEl)fieldEl.value=key==='fee'?value/100:value;}
  if(el.id==='field-product_id'){
    const product=found('products',el.value),form=el.closest('form');
    if(form?.dataset.entity==='order_items'&&product){$('#field-unit_price').value=product.price/100;$('#field-title').value=product.name+' · '+product.sku;}
  }
});
document.addEventListener('submit',async event=>{
  const form=event.target;
  if(form.dataset.opsSearch){event.preventDefault();const q=new FormData(form).get('q');if(form.dataset.opsSearch==='tasks')taskQuery=String(q||'');else leadQuery=String(q||'');render();}
  if(form.id==='task-step-form'){event.preventDefault();const task=found('tasks',form.dataset.task);try{await api('task_steps','POST',{title:String(new FormData(form).get('title')),task_id:task.id,business_id:task.business_id,completed:false});await refresh();taskDetail(task.id);}catch(error){toast(error.message,true);}}
});

boot();
